#![deny(unsafe_code)]

//! C11 data tables (`digaos_ssot_tables.c`) and TypeScript projection (`digaos.ts`) generators for `DigaOS`.

use std::fmt::Write as _;

use super::{DIGAOS_SSOT_CONTRACT_HASH, DigaOsConfigSpec, load_validated_builtin_digaos_config};

fn c_escaped(raw: &str) -> String {
    raw.replace('\\', "\\\\").replace('"', "\\\"")
}

/// Renders `firmware/digaos/generated/digaos_ssot_tables.c` for a validated `DigaOsConfigSpec`.
#[must_use]
pub fn generate_digaos_ssot_tables_for(cfg: &DigaOsConfigSpec) -> String {
    let mut out = String::from(
        "/* AUTO-GENERATED BY panadiga-core::ssot::digaos_header -- DO NOT EDIT MANUALLY. */\n\
         /* HARDWARE-INTEROPERABILITY PROTOTYPE -- NOT LEGALLY CLEAN-ROOM. */\n\
         #include \"generated/digaos_ssot.h\"\n\n",
    );

    out.push_str(
        "const digaos_menu_item_t k_digaos_ssot_menu_items[DIGAOS_SSOT_MENU_ITEM_COUNT] = {\n",
    );
    for menu in &cfg.menus {
        for item in &menu.items {
            let _ = writeln!(
                out,
                "    {{ \"{}\", \"{}\", \"{}\", {}u, {}u, {}u }},",
                c_escaped(&item.id),
                c_escaped(&item.label_key),
                c_escaped(&item.command),
                item.kind,
                item.min_safety_tier,
                u8::from(item.requires_unlock),
            );
        }
    }
    out.push_str("};\n\n");

    out.push_str("const digaos_menu_t k_digaos_ssot_menus[DIGAOS_SSOT_MENU_COUNT] = {\n");
    let mut cursor = 0usize;
    for menu in &cfg.menus {
        let count = menu.items.len();
        let _ = writeln!(
            out,
            "    {{ \"{}\", \"{}\", {}u, {}u }},",
            c_escaped(&menu.id),
            c_escaped(&menu.title_key),
            cursor,
            count,
        );
        cursor += count;
    }
    out.push_str("};\n\n");

    out.push_str("const digaos_theme_t k_digaos_ssot_themes[DIGAOS_SSOT_THEME_COUNT] = {\n");
    for theme in &cfg.themes {
        let _ = writeln!(
            out,
            "    {{ \"{}\", \"{}\", 0x{:04X}u, 0x{:04X}u, 0x{:04X}u, 0x{:04X}u, 0x{:04X}u, {}u, {}u, {}u }},",
            c_escaped(&theme.id),
            c_escaped(&theme.name_key),
            theme.bg_rgb565,
            theme.fg_rgb565,
            theme.accent_rgb565,
            theme.warn_rgb565,
            theme.danger_rgb565,
            theme.osd_font_mode,
            theme.overscan_px,
            theme.contrast_level,
        );
    }
    out.push_str("};\n\n");

    out.push_str(
        "const digaos_power_profile_t k_digaos_ssot_power_profiles[DIGAOS_SSOT_POWER_PROFILE_COUNT] = {\n",
    );
    for prof in &cfg.power_profiles {
        let _ = writeln!(
            out,
            "    {{ \"{}\", \"{}\", \"{}\", {}u, {}u, {}u, {}u, {}u, {}UL, {}u, {}u, {}u }},",
            c_escaped(&prof.id),
            c_escaped(&prof.name_key),
            c_escaped(&prof.soc_core_id),
            prof.tbc_mode,
            prof.aiof_fs0_mode,
            prof.avdd_gain_preset,
            prof.sata_udma_mode,
            prof.dram_refresh_preset,
            prof.uart_baud,
            u8::from(prof.unlock_required),
            u8::from(prof.lethal_mmio_guard),
            u8::from(prof.ipl_ro_guard),
        );
    }
    out.push_str("};\n\n");

    out.push_str(
        "const digaos_soc_target_t k_digaos_ssot_soc_targets[DIGAOS_SSOT_SOC_TARGET_COUNT] = {\n",
    );
    for target in &cfg.soc_targets {
        let _ = writeln!(
            out,
            "    {{ \"{}\", \"{}\", \"{}\", {}u, {}u, {}u, {}UL }},",
            c_escaped(&target.soc_core_id),
            c_escaped(&target.soc_id),
            c_escaped(&target.isa),
            u8::from(target.is_big_endian),
            u8::from(target.mmio_verified),
            u8::from(target.is_primary_executable),
            target.logic_voltage_mv,
        );
    }
    out.push_str("};\n");
    out
}

/// Renders `firmware/digaos/generated/digaos_ssot_tables.c` using builtin `default_digaos_config.json`.
#[must_use]
pub fn generate_digaos_ssot_tables() -> String {
    let cfg = load_validated_builtin_digaos_config();
    generate_digaos_ssot_tables_for(&cfg)
}

/// Renders `apps/desktop/src/models/generated/digaos.ts` for a validated `DigaOsConfigSpec`.
#[must_use]
pub fn generate_ts_digaos_module_for(cfg: &DigaOsConfigSpec, contract_hash: u32) -> String {
    let cfg_json = serde_json::to_string_pretty(cfg)
        .expect("Validated DigaOsConfigSpec must serialize cleanly");
    format!(
        "// AUTO-GENERATED BY panadiga-core::ssot::digaos_header -- DO NOT EDIT MANUALLY.\n\n\
         export const DIGAOS_SSOT_CONTRACT_HASH = 0x{contract_hash:08X};\n\
         export const DIGAOS_SSOT_CONTRACT_HASH_STR = '{contract_hash:08X}';\n\n\
         export interface DigaOsMmioRangeSpec {{\n\
         \x20 readonly start: string;\n\
         \x20 readonly size: number;\n\
         \x20 readonly note: string;\n\
         }}\n\n\
         export interface DigaOsMenuItemSpec {{\n\
         \x20 readonly id: string;\n\
         \x20 readonly label_key: string;\n\
         \x20 readonly command: string;\n\
         \x20 readonly kind: number;\n\
         \x20 readonly min_safety_tier: number;\n\
         \x20 readonly requires_unlock: boolean;\n\
         }}\n\n\
         export interface DigaOsMenuSpec {{\n\
         \x20 readonly id: string;\n\
         \x20 readonly title_key: string;\n\
         \x20 readonly items: readonly DigaOsMenuItemSpec[];\n\
         }}\n\n\
         export interface DigaOsThemeSpec {{\n\
         \x20 readonly id: string;\n\
         \x20 readonly name_key: string;\n\
         \x20 readonly bg_rgb565: string;\n\
         \x20 readonly fg_rgb565: string;\n\
         \x20 readonly accent_rgb565: string;\n\
         \x20 readonly warn_rgb565: string;\n\
         \x20 readonly danger_rgb565: string;\n\
         \x20 readonly osd_font_mode: number;\n\
         \x20 readonly overscan_px: number;\n\
         \x20 readonly contrast_level: number;\n\
         }}\n\n\
         export interface DigaOsPowerProfileSpec {{\n\
         \x20 readonly id: string;\n\
         \x20 readonly name_key: string;\n\
         \x20 readonly soc_core_id: string;\n\
         \x20 readonly tbc_mode: number;\n\
         \x20 readonly aiof_fs0_mode: number;\n\
         \x20 readonly avdd_gain_preset: number;\n\
         \x20 readonly sata_udma_mode: number;\n\
         \x20 readonly dram_refresh_preset: number;\n\
         \x20 readonly uart_baud: number;\n\
         \x20 readonly unlock_required: boolean;\n\
         \x20 readonly lethal_mmio_guard: boolean;\n\
         \x20 readonly ipl_ro_guard: boolean;\n\
         \x20 readonly allowed_mmio_writes: readonly DigaOsMmioRangeSpec[];\n\
         }}\n\n\
         export interface DigaOsSocTargetSpec {{\n\
         \x20 readonly soc_core_id: string;\n\
         \x20 readonly soc_id: string;\n\
         \x20 readonly isa: string;\n\
         \x20 readonly is_big_endian: boolean;\n\
         \x20 readonly mmio_verified: boolean;\n\
         \x20 readonly is_primary_executable: boolean;\n\
         \x20 readonly logic_voltage_mv: number;\n\
         }}\n\n\
         export interface DigaOsConfigSpec {{\n\
         \x20 readonly schema_version: string;\n\
         \x20 readonly prompt: string;\n\
         \x20 readonly menus: readonly DigaOsMenuSpec[];\n\
         \x20 readonly themes: readonly DigaOsThemeSpec[];\n\
         \x20 readonly power_profiles: readonly DigaOsPowerProfileSpec[];\n\
         \x20 readonly soc_targets: readonly DigaOsSocTargetSpec[];\n\
         }}\n\n\
         export const DIGAOS_CONFIG: DigaOsConfigSpec = {cfg_json};\n"
    )
}

/// Renders `apps/desktop/src/models/generated/digaos.ts` using builtin `default_digaos_config.json`.
#[must_use]
pub fn generate_ts_digaos_module() -> String {
    let cfg = load_validated_builtin_digaos_config();
    generate_ts_digaos_module_for(&cfg, DIGAOS_SSOT_CONTRACT_HASH)
}
